package poll

import (
	"context"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	src := &FakeSource{Err: ErrNotReady}
	_, _ = Poll(ctx, src, "k")
	if src.Calls() > 1 {
		t.Fatalf("Poll with a cancelled context made %d Get calls, want 1", src.Calls())
	}
}
